E["70:002b3447"] = "Щоб забути лише одного персонажа, клацніть X на його картці у вкладці «Альти»."
E["70:40bc7115"] = "Користуєтесь іншим аддоном для риболовлі? Вимкніть це — вікно риболовлі залишається."
E["70:51cf83bf"] = "Список майстрів на getmastercraft.com відкривається для всіх 1 січня"
E["70:979262e1"] = "Китайський шрифт не вдалося завантажити, тому інтерфейс лишається англійською."
E["70:e35a24e3"] = "Вивчіть навичку Риболовля. Навчає: Учитель Рибальства; ранг Підмайстер - там само на 50."
E["71:0d539f49"] = "Календар гри ще не показує дат - він заповнюється, коли вони наближаються."
E["71:1edb11e5"] = "Вивчіть ранг Підмайстер професії Гірнича справа при 50 умінні (рівень 10). Навчає: Інструктор Гірничої Справи."
E["71:3f5ee208"] = "Щоб розчаклувати його, потрібен персонаж з професією Накладання чарів: альт, друг або ваша гільдія."
E["71:4f421a75"] = "Королекров - від 125, життєкорінь - від 150. «Експерт» - на 125 (рівень 20)."
E["71:53b93df7"] = "Ловіть рибу у водах, що відповідають вашому вмінню - надто низьке, і здебільшого ловитиметься мотлох."
E["71:748ed3d8"] = "На аукціоні натисніть «Сканувати ціни», щоб побачити справжню вартість і поради щодо здобичі."
E["71:b7204111"] = "Видобувайте тут і мідь, і срібло. «Експерт» - на 125 (рівень 20)."
E["72:28dfaf29"] = "Введіть |cffffd140/reload|r, щоб перемкнути зараз (під час бою це неможливо)."
E["72:6ef14bab"] = "Те, що ще потрібно вашим посібникам і трекеру предметів, не потрапляє до продажу."
E["72:905b952f"] = "Рецептів ще не збережено - відкрийте вікно кожної професії один раз і спробуйте знову."
E["72:c547025d"] = "Жоден із цих рецептів не дає предмет, який купує торговець - враховується найбільше золота."
E["72:e039cc34"] = "Наставник Орди тут: Дранг (Степи). «Експерт» - на 125 (рівень 20)."
E["73:0d3bc05f"] = "Тут поки нічого - знайдіть предмет вище або перетягніть його сюди зі своїх сумок."
E["73:38c21f8f"] = "Прив'язаний до душі: його не можна виставити на аукціон, а ви не маєте професії Накладання чарів."
E["73:4b45ce8b"] = "Налаштування > Точки > Показувати точки: вимкнено - клацніть, щоб показувати їх під час збору."
E["73:73d1256c"] = "Цін ще немає - відкрийте аукціон і натисніть «Сканувати ціни» (угорі праворуч)."
E["73:7578ed73"] = "Зараз у мережі немає інших майстрів Mastercraft на вашому сервері та у вашій фракції."
E["73:b83eab2e"] = "Mastercraft сам приєднується до своєї мережі - вручну приєднувати не треба."
E["73:fd0ce9d6"] = "Увімкніть Auctionator, щоб обирати. Без нього Mastercraft використовує власне сканування."
E["74:070e4ce0"] = "Вони показуються під час збору - після «Почати збір». Більше - у Налаштування > Точки."
E["74:50625cd5"] = "На 125: вивчіть «Експерт» - книга «Експертна Кулінарна Книга», 1 золото: Шандріна (Ясенеділ)"
E["74:64539fe5"] = "GatherMate2Data вимкнено, тож імпортовано лише точки, які мав GatherMate2."
E["74:78ad960a"] = "Уб'йте: Коваль Мечів Чорної Варти (Стратгольм) і принесіть його знак розрізнення."
E["74:7b524f39"] = "Зараз у мережі немає інших майстрів Mastercraft на вашому сервері та у вашій фракції."
E["74:b813f560"] = "Поки нічого - дописи WTS і WTB з торгового чату з'являтимуться тут одразу."
E["74:df1c35f3"] = "Спершу дістаньте матеріали з вашого банку - «Забрати матеріали» у банку робить це."
E["75:46498a29"] = "Titan Panel від HonorGoG, urnati - панель, що показує запуск Mastercraft"
E["75:4dcd4890"] = "1 стос залишається у ваших сумках - кнопка спорядження обирає, що йде до банку."
E["75:55517b16"] = "Трави будь-якого кольору, крім сірого, дають вміння - збирайте все на своєму маршруті."
E["75:8a65f66f"] = "Панель риболовлі не перетягнеться випадково. Вимкніть, щоб знову її рухати."
E["75:9b2ea211"] = "Знайдіть майстра у списку майстрів на getmastercraft.com і напишіть йому."
E["76:156fad8b"] = "Розчаклувати: за скільки продаються його матеріали на аукціоні, після комісії."
E["76:244cf077"] = "Поза списками - його золото й предмети більше не враховуються, його рецепти все ще враховуються."
E["76:3d672637"] = "1. Установіть GatherMate2 і GatherMate2Data та увімкніть обидва - потрібні обидва."
E["76:7d7f1516"] = "Жоден із цих рецептів ще не має ціни на аукціоні - рахується найбільше золота."
E["76:98af16f1"] = "Ви ще не сканували аукціон - натисніть «Сканувати ціни», щоб отримати ціни."
E["76:a6dd6e57"] = "Auctionator від plusmouse, borjamacare - ціни аукціону та список покупок"
E["76:ca9e4695"] = "Головна сторінка радить, що варто зробити просто зараз. Оберіть потрібні поради."
E["76:cca7809e"] = "Поки нічого не зібрано. Добувайте руду, збирайте трави, здирайте шкури чи беріть здобич - усе з'явиться тут."
E["77:1fcbef90"] = "Вивчіть ранг Ремісник на 200 (рівень 35). Навчає: Інструктор Гірничої Справи. Зробіть це до межі 225."
E["77:57d6d1e5"] = "LibDataBroker-1.1 від tekkub, Elkano - запуск Mastercraft на панелях Broker"
E["78:5e5d41cb"] = "Ваш ранг і ваше уміння: Риболовля, зі шкалою до найвищого рангу, якого ви можете досягти зараз."
E["78:73122ab1"] = "Оберіть, що Mastercraft додає під предметом - миша на пункті показує, як це виглядає"
E["78:8cae7130"] = "У сумках немає вудки. Їх продають торговці."
E["78:962153a1"] = "Уже враховує те, що є в кожного персонажа (сумки, а банк - після відвідування)."
E["78:c0a5894b"] = "Блискуча Цяцька (Риболовля +25) від торговця ремісничими чи рибальськими товарами підвищує ваше вміння."
E["78:c18fb0af"] = "Двічі клацніть правою кнопкою по воді, щоб закинути. Клацніть правою по поплавку, коли він сплескує."
E["78:e217832b"] = "Прив'язаний до душі: розчаклувати його може лише той персонаж, що його виготовив, - за допомогою професії Накладання чарів."
E["78:e31dfe1e"] = "|cffe65454Немає у вашій грі|r  |cff5c6373- оберіть інший рецепт цього кольору|r"
E["78:f39d7aaf"] = "Жезли для накладання чарів - їх виготовляють ковалі (Мідний Жезл продають і торговці)"
E["79:5116986a"] = "Усе це можна змінити в налаштуваннях або запустити цей посібник знову командою /mc setup."
E["79:6e9713c1"] = "Уб'йте: Тіньова Мисливиця Вош'ґаджин (Шпиль Блекрок) і принесіть її зміїний камінь."
E["79:7630ef09"] = "Наставник: Тувд (Орґріммар) / Балтус Стоунфлеєр (Залізогарт). «Підмайстер» на 50."
E["79:7f63eaf9"] = "Грецький, російський і польський шрифт: Noto Sans від Google (SIL Open Font License 1.1)"
E["79:8ea804c9"] = "Для цих предметів немає порад у підказках, у Золото > Порадник зі здобичі та в помічнику пошти."
E["79:bebc95ae"] = "«Ремісник» дає завдання Нета Пеґла (Бруднолипка трясовина, див. попередній крок)."
