E["80:1ff5e5c6"] = "Кількості за кожною ціною перевірено не всі - усі найнижчі ціни збережено."
E["80:2713d6ee"] = "Звідки береться кожен матеріал і рецепт, і хто у вашій гільдії що може виготовити"
E["80:30efb485"] = "Пауза, поки ви шукаєте - триває сама через 3 секунди після вашого останнього пошуку."
E["80:666de964"] = "Панель риболовлі без улову цього сеансу — стрілка на панелі робить те саме."
E["80:aba00a1e"] = "Якщо таке станеться, Mastercraft блокує гравця на 7 днів і показує його тут."
E["80:b3af5e90"] = "Час риболовлі рахується лише поки ви ловите. Вартість — за цінами, які є зараз."
E["80:c9b20720"] = "Жоден із цих рецептів не дає спорядження, яке можна розчаклувати - рахується найбільше золота."
E["80:dd5cb624"] = "Оберіть клавішу для відкриття Mastercraft: меню гри > Прив'язки клавіш > Аддони > Mastercraft."
E["80:e5859fac"] = "Розмір вікна Mastercraft (Налаштування > Загальне) також збільшує чи зменшує їх."
E["81:196cf609"] = "Ваш статус - вимкнено: інші гравці не бачать вас як майстра. Ви їх усе ще бачите."
E["81:34882b17"] = "Лише нотатка для себе. Кроки також позначаються самі, щойно ваше вміння їх проходить."
E["81:400834d0"] = "Пурпуровий лотос теж. Примарний гриб (245) росте в печерах, здебільшого у Внутрішніх землях."
E["81:915b5f9e"] = "Середня з 5 найдешевших: один предмет, виставлений надто дешево, не знижує ціну."
E["81:c0775355"] = "Не бачите кнопку «Сканувати ціни»? Введіть |cffffd140/mc scan|r на аукціоні."
E["82:224895ae"] = "Чумоцвіт росте лише в Зачумлених землях і Сквернолісі. Льодошапка (290): Зимоключ."
E["82:50f3c6b9"] = "Поки ви ловите, ви все одно чуєте сплеск, коли перед грою інше вікно."
E["82:5eed2a33"] = "Золото: як часто там клює те, що ви шукали. Клік показує зону докладно."
E["82:9f8c656c"] = "У Wowhead Forever ще немає Рибальського Фестивалю. Він з'явиться тут, щойно з'явиться там."
E["82:bfc7fe29"] = "Ви ще не сканували аукціон - натисніть там «Сканувати ціни», щоб отримати ціни."
E["82:dd278712"] = "Мінус те, що вже є в будь-якого персонажа, за цінами вашого сканування аукціону."
E["83:1017f1bc"] = "Аукціон утримує 5% від кожного продажу. Увімкнено: прибуток показує золото, яке ви справді отримуєте."
E["83:473a439d"] = "Ви отримаєте маленьке спливне вікно, коли у мережі з'явиться майстер, що це виготовляє, - один раз на майстра."
E["83:77005bb8"] = "Один раз відкрийте вікно професії Кулінарія, щоб Mastercraft знав, які з цих рецептів у вас є."
E["83:7957d24c"] = "Користуєтеся іншим аддоном для риболовлі? Вимкніть це - сторінка Риболовля у розділі «Професії» залишається."
E["83:91f93f74"] = "Розмір вікна Mastercraft (Налаштування > Загальне) робить панель більшою або меншою."
E["83:c553258e"] = "Принесіть своєму майстру зразки ваших виробів з істот типу Скорпід і докази того, що ви можете дістати драконячу луску."
E["84:0ff13d45"] = "Натисніть «Стежити за списком», і наступне «Сканувати ціни» перевірить, скільки лотів виставлено на кожній ціні."
E["84:41e4d5c8"] = "Використання: /mc ask <майстер> <рецепт>  - напр. /mc ask Andreddi Moonchild Зернистий Динаміт"
E["84:4de0f3d3"] = "LibDBIcon-1.0 від Funkeh, nebula169 - кнопка на мінікарті в збирачах кнопок мінікарти"
E["84:6c864ecb"] = "Один короткий рядок, який покупці бачать поряд із вашим ім'ям, до 40 літер. Лише простий текст."
E["84:ac9ddcc7"] = "Спершу увімкніть GatherMate2 і GatherMate2Data (список додатків на екрані персонажа)."
E["85:2a897b5b"] = "На 55 рівні (для завдань потрібен 40-й) шкірник може обрати один із трьох шляхів."
E["85:2c7b26a0"] = "Зараз замовлень немає. Подайте своє - майстри, які знають рецепт, зроблять вам пропозицію."
E["85:35712bad"] = "Mastercraft сканує аукціон, щоб дізнатися ціни. Наведіть на будь-який вибір, щоб побачити, що він робить."
E["85:4ea07f6b"] = "Ціни з Auctionator. Скануйте аукціон через Mastercraft, щоб отримати свіжіші дані."
E["85:54162222"] = "Ціна TradeSkillMaster, щойно вона є для предмета, інакше - найновіша з інших"
E["85:577123a0"] = "Arcana (раніше ChocolateBar) від kiatra_ - панель, що показує запуск Mastercraft"
E["85:70a21821"] = "Завдання |cffeef0f5Широкі простори|r (6 рівень), потім |cffeef0f5Табірна наука 101: кулінарія|r"
E["85:7a3ad26b"] = "Вони показуються під час збору - «Пошук Мінералів» або «Пошук трав» увімкнено. Більше - у Налаштування > Точки."
E["85:9f38d001"] = "Піймали одну з трьох рідкісних риб? Рибобот 5000 обміняє її на приз - вони нижче."
E["86:71d44004"] = "Ваш статус повертається сам, коли ви повертаєтеся, - статус, який ви обрали самі, зберігається."
E["86:94c9870e"] = "Не приєднано: гра зараз утримує чат-канали - Mastercraft сам спробує ще раз"
E["86:98204b79"] = "Не надсилається: інші не бачать цю професію і не знаходять вас для неї. Натисніть, щоб знову додати її до списку."
E["86:ca44ff3b"] = "Ваше вікно професій не показує цього рецепта, тож у вашій грі його, схоже, немає."
E["86:e3b515fc"] = "На 225 (рівень 35): завдання «Екстремальна риболовля Нета Пеґла» (Бруднолипка трясовина) відкриває «Ремісник»."
E["86:e87ac13d"] = "Жодного відомого рецепта - відкрийте вікна професій один раз, щоб Mastercraft їх вивчив."
E["86:fe440a16"] = "Під час збору: «Пошук Мінералів» або «Пошук трав» увімкнено - не в містах, підземеллях чи бою."
E["87:5cfad606"] = "Беззбитковість: найнижча ціна, що повертає вашу вартість після 5% комісії аукціону."
E["88:1fe84525"] = "Гра малює персонажа, лише поки ви ним граєте - увійдіть цим персонажем, щоб побачити його тут."
E["88:8ebd109e"] = "Налаштування > Підказки: вимкніть «Залишати спорядження для риболовлі, їжу й напої», щоб отримувати поради щодо них."
E["89:038f6a26"] = "Кнопка виготовляє, щойно матеріали у ваших сумках і відкрито вікно професії."
E["89:0d5b03c1"] = "Він знову відкриється, коли ви наступного разу візьмете вудку. Налаштування > Рибалка вимикає його."
E["89:16e8cd98"] = "Гра не дозволила Mastercraft перезавантажити інтерфейс - введіть |cffffd140/reload|r, щоб зробити це."
E["89:3be60f4b"] = "Те, що ви носили до риболовлі, зокрема зброя, повертається, коли панель риболовлі закривається."
E["89:3e48f85a"] = "Панель риболовлі не видно — ваша клавіша риболовлі все ще ловить. /mc fish повертає її."
